def pattern_matching(text: str, pattern: str) -> list[int]:
    """Finds all starting positions of Pattern in Text (0-based indexing)."""
    positions = []
    pattern_len = len(pattern)
    
    for i in range(len(text) - pattern_len + 1):
        if text[i : i + pattern_len] == pattern:
            positions.append(i)
            
    return positions


def pattern_matching_from_file(genome_filepath: str, pattern: str, output_filepath: str = None) -> list[int]:
    """
    Reads a genome sequence from a file, searches for a pattern,
    and optionally writes the space-separated positions to an output file.
    """
    with open(genome_filepath, 'r') as file:
        # Read the sequence and strip whitespace/newlines (handles FASTA headers if present)
        lines = file.readlines()
        if lines[0].startswith('>'):
            text = "".join(line.strip() for line in lines[1:])
        else:
            text = "".join(line.strip() for line in lines)
            
    positions = pattern_matching(text, pattern)
    
    # Optional: Write results directly to an output file
    if output_filepath:
        with open(output_filepath, 'w') as out_file:
            out_file.write(" ".join(map(str, positions)))
        print(f"Results successfully written to {output_filepath}")
        
    return positions


